(()=>{const money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';fetch('/assets/menu-start.json').then(r=>r.json()).then(d=>{const cats=d.categories.filter(c=>c.items.some(i=>i.active)).sort((a,b)=>a.sort-b.sort);const nav=document.querySelector('#menu-categories'),list=document.querySelector('#menu-list');nav.innerHTML=cats.map((c,i)=>`<a href="#cat-${i}">${c.name}</a>`).join('');list.innerHTML=cats.map((c,i)=>`<section class="menu-cat" id="cat-${i}"><h2>${c.name}</h2><div class="menu-grid">${c.items.filter(x=>x.active).map(x=>`<article class="menu-item"><div><h3>${x.name}</h3>${x.description?`<p>${x.description}</p>`:''}${x.weight||x.volume?`<small>${x.weight||x.volume}</small>`:''}${x.variants?`<small>Варианты: ${x.variants.join(', ')}</small>`:''}</div><strong>${money(x.price)}</strong></article>`).join('')}</div></section>`).join('')}).catch(()=>{document.querySelector('#menu-list').textContent='Меню временно недоступно.';});})();
